/* eslint-disable */
/** Internal type. DO NOT USE DIRECTLY. */
type Exact<T extends { [key: string]: unknown }> = { [K in keyof T]: T[K] };
/** Internal type. DO NOT USE DIRECTLY. */
export type Incremental<T> = T | { [P in keyof T]?: P extends ' $fragmentName' | '__typename' ? T[P] : never };
import type { TypedDocumentNode as DocumentNode } from '@graphql-typed-document-node/core';
export type AppFilter = {
  envs?: Array<string> | null | undefined;
  /** A framework, as collected (symfony, laravel…), and its version. */
  framework?: VersionConstraint | null | undefined;
  projects?: Array<string> | null | undefined;
  /** A runtime (php, node…) and its version. */
  runtime?: VersionConstraint | null | undefined;
  search?: string | null | undefined;
};

export type AppSort = {
  by: AppSortField;
  desc?: boolean | null | undefined;
};

export type AppSortField =
  | 'ENV'
  | 'FRAMEWORK'
  | 'HOSTNAME'
  | 'NAME'
  | 'PROJECT'
  /** The code deployed: tag or branch. */
  | 'VERSION';

export type CreateUserInput = {
  firstName?: string | null | undefined;
  lastName?: string | null | undefined;
  /** 8 characters at least. */
  password: string;
  roles?: Array<string> | null | undefined;
  username: string;
};

export type EnvironmentInput = {
  name?: string | null | undefined;
};

/** A resource a role grants out of the namespaces; ALL is every one. */
export type GlobalGrant =
  | 'ALL'
  | 'ICONS'
  | 'NAMESPACES'
  | 'ROLES'
  | 'TASKS'
  | 'TOKENS'
  | 'USERS';

export type GlobalPermissionInput = {
  action: GrantAction;
  resource: GlobalGrant;
};

/** An action a role grants; ALL is every one. Write does not imply read. */
export type GrantAction =
  | 'ALL'
  | 'READ'
  | 'WRITE';

export type GraphFilter = {
  /** The links of these confidences; all by default. */
  confidences?: Array<LinkConfidence> | null | undefined;
  /** Slugs. */
  envs?: Array<string> | null | undefined;
  /**
   * Project, host or stack nodes to draw with their content, at the levels of the projects and the
   * hosts: their apps, services, webservers and runtimes, those of the same kind and name merged, in
   * the group of the same id.
   */
  expand?: Array<string> | null | undefined;
  /** Whether the external targets show. */
  externals?: boolean | null | undefined;
  /** Hostnames; a host named leaves its stack. */
  hosts?: Array<string> | null | undefined;
  /** Slugs. */
  projects?: Array<string> | null | undefined;
  /** The hosts of these statuses and their content; ACTIVE and STALE by default. */
  status?: Array<HostStatus> | null | undefined;
};

export type GraphLevel =
  /** Apps, services and proxies grouped by host, the local webserver and php-fpm folded into the apps. */
  | 'APP'
  /** A node per host, the similar hosts stacked, the external targets of an env merged. */
  | 'HOST'
  /** A node per project and env, the external targets of an env merged. */
  | 'PROJECT';

export type GraphNodeKind =
  | 'APP'
  | 'EXTERNAL'
  | 'HOST'
  | 'PROJECT'
  /** A runtime of a host, only in an expanded node. */
  | 'RUNTIME'
  | 'SERVICE'
  /** A webserver left a node: a proxy routing to other hosts. */
  | 'WEBSERVER';

export type HistoryFilter = {
  /** host, runtime, service, webserver, app or link. */
  entityType?: string | null | undefined;
  hostname?: string | null | undefined;
  /** Lists the events in the order they occurred; the latest first otherwise. */
  oldestFirst?: boolean | null | undefined;
  since?: string | null | undefined;
};

/** The projects and envs filters take slugs; search matches names case-insensitively. */
export type HostFilter = {
  envs?: Array<string> | null | undefined;
  projects?: Array<string> | null | undefined;
  search?: string | null | undefined;
  status?: Array<HostStatus> | null | undefined;
};

/** The order of a listing; ties are broken by name. */
export type HostSort = {
  by: HostSortField;
  desc?: boolean | null | undefined;
};

export type HostSortField =
  | 'APPS'
  | 'ENV'
  | 'HOSTNAME'
  /** The address of the default route, else the first. */
  | 'IP'
  | 'LAST_SEEN'
  | 'OS'
  | 'PROJECT'
  /** Freshest first. */
  | 'STATUS';

export type HostStatus =
  | 'ACTIVE'
  /** No snapshot for longer than its inactiveAfter. */
  | 'INACTIVE'
  /** No snapshot for longer than the staleAfter of the namespace. */
  | 'STALE';

export type ImpactDirection =
  /** What stops working when the node does. */
  | 'DEPENDENTS'
  /** What the node needs to work. */
  | 'NEEDS';

export type LinkConfidence =
  | 'AMBIGUOUS'
  | 'EXACT'
  | 'INFERRED';

/** A resource a role grants on namespaces; ALL is every one. */
export type NamespaceGrant =
  | 'ALL'
  | 'INVENTORY'
  | 'METADATA';

export type NamespaceInput = {
  description?: string | null | undefined;
  /** Seconds after which it is inactive; longer than staleAfter. */
  inactiveAfter?: number | null | undefined;
  name?: string | null | undefined;
  /** Seconds the snapshots are kept. */
  snapshotRetention?: number | null | undefined;
  /** Seconds without snapshot after which a host is stale; a minute at least. */
  staleAfter?: number | null | undefined;
};

export type NamespacePermissionInput = {
  action: GrantAction;
  /** Null for every namespace. */
  namespace?: string | null | undefined;
  resource: NamespaceGrant;
};

export type NetworkInput = {
  description?: string | null | undefined;
  /** private or public. */
  kind?: string | null | undefined;
  name?: string | null | undefined;
};

/** A page of a listing: limit is capped at 500. */
export type PageInput = {
  limit?: number | null | undefined;
  offset?: number | null | undefined;
};

export type ProjectInput = {
  description?: string | null | undefined;
  name?: string | null | undefined;
};

export type RoleInput = {
  code: string;
  description?: string | null | undefined;
  globalPermissions?: Array<GlobalPermissionInput> | null | undefined;
  oidcGroups?: Array<string> | null | undefined;
  /**
   * With globalPermissions, they replace the permissions of the role; both left out, they stay. The
   * admin role keeps every permission: it takes neither.
   */
  permissions?: Array<NamespacePermissionInput> | null | undefined;
};

export type ServiceFilter = {
  envs?: Array<string> | null | undefined;
  projects?: Array<string> | null | undefined;
  search?: string | null | undefined;
  types?: Array<string> | null | undefined;
};

export type ServiceSort = {
  by: ServiceSortField;
  desc?: boolean | null | undefined;
};

export type ServiceSortField =
  | 'HOSTNAME'
  | 'TYPE'
  | 'VERSION';

/** A field left out stays; a name set empty is cleared. */
export type UpdateUserInput = {
  firstName?: string | null | undefined;
  lastName?: string | null | undefined;
  password?: string | null | undefined;
};

/**
 * A framework or a runtime, and a version it compares to, part by part: 7.10 is above 7.9. The
 * version of an app is cut to the parts given, so that EQ 7.4 takes 7.4.33 and GT 7.4 starts at
 * 7.5. No version takes every version.
 */
export type VersionConstraint = {
  name: string;
  op?: VersionOp | null | undefined;
  version?: string | null | undefined;
};

export type VersionOp =
  | 'EQ'
  | 'GT'
  | 'GTE'
  | 'LT'
  | 'LTE';

